// The only module that imports @earendil-works/*. It binds the engine port to pi's Agent, resolves models, and
// carries engine records inside pi's transcript. Every plugin rule lives behind the Engine port.

import { Agent, type AgentMessage, type AgentTool, type StreamFn } from '@earendil-works/pi-agent-core'
import { envApiKeyAuth, validateToolArguments, type Api, type AssistantMessage, type Message, type Model, type TSchema } from '@earendil-works/pi-ai'
import { openAICompletionsApi } from '@earendil-works/pi-ai/api/openai-completions.lazy'
import { createModels, createProvider } from '@earendil-works/pi-ai/models'
import { builtinModels } from '@earendil-works/pi-ai/providers/all'
import { parseCatalog } from './catalog.ts'
import { createEngine, type Engine, type Turn, type Validate } from './engine.ts'
import type { JsonObject, JsonValue, ToolResult } from './plugin.ts'
import type { EngineRecord, ModelSpec, RunResult, Session, SessionEvent, SessionOptions, Transcript } from './session.ts'

/** Engine records ride in pi's transcript under their own role; convertToLlm drops them. */
interface RecordMessage {
  readonly role: 'aigent'
  readonly record: EngineRecord
  readonly timestamp: number
}

declare module '@earendil-works/pi-agent-core' {
  interface CustomAgentMessages {
    aigent: RecordMessage
  }
}

export interface ResolvedModel {
  readonly model: Model<Api>
  readonly streamFn: StreamFn
  /** The model's API key under its env var name, so it is redacted like any host secret. */
  readonly secrets: Readonly<Record<string, string>>
}

const TRANSCRIPT_FORMAT = 'aigent-transcript/1'

export async function createSession(options: SessionOptions): Promise<Session> {
  return startSession(options, await resolveModel(options.model))
}

/** `createSession` with the model already resolved. The adapter's offline test passes pi's faux provider here. */
export async function startSession(options: SessionOptions, resolved: ResolvedModel): Promise<Session> {
  if (options.systemPrompt !== undefined && options.transcript !== undefined) throw new Error('pass systemPrompt or transcript, not both')
  const resumed = options.transcript && parseTranscript(options.transcript)
  const listeners = new Set<(event: SessionEvent) => void>()
  const writeLog = options.log ?? ((line: string) => console.error(`[aigent] ${line}`))
  // Nobody can subscribe before createSession returns, so this never runs before `engine` exists.
  const dispatch = (event: SessionEvent): void => {
    for (const listener of listeners) {
      try {
        listener(redactJson(event, engine.redact))
      } catch (error) {
        writeLog(engine.redact(`listener threw: ${messageOf(error)}`))
      }
    }
  }

  const secrets = { ...options.secrets, ...resolved.secrets }
  const engine: Engine = await createEngine({
    catalog: parseCatalog(options.plugins),
    toolMode: options.toolMode ?? 'native',
    start: resumed ? { kind: 'resume', records: resumed.records } : { kind: 'fresh', systemPrompt: options.systemPrompt ?? '' },
    enabled: options.enabled ?? [],
    secrets,
    maxTurns: options.maxTurns ?? 25,
    hookTimeoutMs: options.hookTimeoutMs ?? 10_000,
    validate: piValidate,
    emit: dispatch,
    log: writeLog,
  })

  const agentTools = (): AgentTool[] =>
    engine.tools().map((spec) => ({
      name: spec.name,
      label: spec.name,
      description: spec.description,
      parameters: spec.parameters as unknown as TSchema,
      execute: async (toolCallId, params, signal) => {
        const result = await engine.callTool({ id: toolCallId, name: spec.name, args: params as JsonObject }, signal ?? new AbortController().signal)
        return toAgentResult(result)
      },
    }))
  const wrap = (record: EngineRecord): RecordMessage => ({ role: 'aigent', record, timestamp: Date.now() })

  // The last assistant message finishTurn reported, so a run pi ends without calling it still gets its turn.
  let reported: AgentMessage | undefined
  const agent = new Agent({
    initialState: { model: resolved.model, systemPrompt: engine.systemPrompt, tools: agentTools(), messages: resumed?.messages ?? [] },
    streamFn: resolved.streamFn,
    convertToLlm: (messages) => messages.filter((m): m is Message => m.role !== 'aigent'),
    // Runs before pi declares tool changes, so the new declarations land ahead of the request that can use them.
    prepareNextTurnWithContext: (turn) => ({ context: { ...turn.context, tools: agentTools() }, messages: engine.takeRecords().map(wrap) }),
    finishTurn: async (turn) => {
      reported = turn.message
      return (await engine.endTurn(toTurn(turn.message))) === 'stop' ? { action: 'end' } : undefined
    },
  })
  const text = holdBack(Math.max(0, ...Object.values(secrets).map((v) => v.length)), engine.redact, (delta) => dispatch({ type: 'text', delta }))
  agent.subscribe((event) => {
    if (event.type === 'message_update' && event.assistantMessageEvent.type === 'text_delta') text.push(event.assistantMessageEvent.delta)
    // pi ends every assistant message this way, whether it finished, errored or was aborted.
    else if (event.type === 'message_end') text.flush()
  })

  const flush = (): void => {
    const records = engine.takeRecords()
    if (records.length > 0) agent.state.messages = [...agent.state.messages, ...records.map(wrap)]
  }
  flush()

  let running: AbortController | undefined
  let closed: Promise<void> | undefined

  return {
    async prompt(text, { signal } = {}) {
      if (closed) throw new Error('session is closed')
      if (running) throw new Error('a prompt is already running')
      const controller = new AbortController()
      running = controller
      const runSignal = signal ? AbortSignal.any([signal, controller.signal]) : controller.signal
      const onAbort = () => agent.abort()
      runSignal.addEventListener('abort', onAbort, { once: true })
      try {
        const content = await engine.beginPrompt(text, runSignal)
        agent.state.tools = agentTools()
        reported = undefined
        const run = agent.prompt([...engine.takeRecords().map(wrap), { role: 'user', content, timestamp: Date.now() }])
        // agent.prompt registers its run synchronously, so an abort that fired before it started still lands.
        if (runSignal.aborted) agent.abort()
        await run
        const last = agent.state.messages.at(-1)
        if (last?.role === 'assistant' && last !== reported) await engine.endTurn(toTurn(last))
        flush()
        return engine.endRun()
      } finally {
        runSignal.removeEventListener('abort', onAbort)
        running = undefined
      }
    },

    async enable(name) {
      await engine.enable(name)
      if (!running) flush()
    },

    subscribe(listener) {
      listeners.add(listener)
      return () => listeners.delete(listener)
    },

    transcript() {
      const messages = JSON.parse(JSON.stringify(agent.state.messages)) as AgentMessage[]
      return { format: TRANSCRIPT_FORMAT, messages: messages.map((m) => exportMessage(m, engine.redact)) as unknown as JsonValue[] }
    },

    close() {
      closed ??= (async () => {
        running?.abort()
        await agent.waitForIdle()
        flush()
        await engine.close()
      })()
      return closed
    },
  }
}

async function resolveModel(spec: ModelSpec): Promise<ResolvedModel> {
  if (spec.kind === 'openai-compatible') {
    const key = process.env[spec.apiKeyEnv]
    if (!key) throw new Error(`${spec.apiKeyEnv} is not set`)
    const models = createModels()
    models.setProvider(
      createProvider({
        id: 'openai-compatible',
        baseUrl: spec.baseUrl,
        auth: { apiKey: envApiKeyAuth(spec.apiKeyEnv, [spec.apiKeyEnv]) },
        models: [
          {
            id: spec.id,
            name: spec.id,
            api: 'openai-completions',
            baseUrl: spec.baseUrl,
            provider: 'openai-compatible',
            type: 'chat',
            reasoning: spec.reasoning ?? true,
            input: ['text'],
            cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0 },
            contextWindow: spec.contextWindow ?? 131_072,
            maxTokens: spec.maxTokens ?? 8192,
          },
        ],
        api: openAICompletionsApi(),
      }),
    )
    const model = models.getModel('openai-compatible', spec.id)
    if (!model) throw new Error(`model ${spec.id} did not register`)
    return { model, streamFn: (m, context, o) => models.streamSimple(m, context, o), secrets: { [spec.apiKeyEnv]: key } }
  }
  const models = builtinModels()
  const model = models.getModel(spec.provider, spec.id)
  if (!model) throw new Error(`unknown model ${spec.provider}/${spec.id}`)
  const key = (await models.getAuth(model))?.auth.apiKey
  return { model, streamFn: (m, context, o) => models.streamSimple(m, context, o), secrets: key ? { MODEL_API_KEY: key } : {} }
}

const piValidate: Validate = (schema, args, name) => {
  try {
    const tool = { name, description: '', parameters: schema as unknown as TSchema }
    const valid: JsonObject = validateToolArguments(tool, { type: 'toolCall', id: '', name, arguments: args as Record<string, never> })
    return { ok: true, args: valid }
  } catch (error) {
    return { ok: false, error: messageOf(error) }
  }
}

function toAgentResult(result: ToolResult) {
  return { content: result.content.map((c) => ({ ...c })), details: undefined, ...(result.isError ? { isError: true } : {}) }
}

function toTurn(message: AssistantMessage): Turn {
  if (message.stopReason === 'aborted') return { kind: 'aborted' }
  if (message.stopReason === 'error') return { kind: 'error', message: message.errorMessage ?? 'model request failed' }
  return { kind: 'ok', text: message.content.flatMap((c) => (c.type === 'text' ? [c.text] : [])).join('') }
}

/** Resume boundary: the format tag and a role on every message. Records are parsed by the engine. */
function parseTranscript(transcript: Transcript): { readonly messages: AgentMessage[]; readonly records: readonly unknown[] } {
  if (transcript?.format !== TRANSCRIPT_FORMAT || !Array.isArray(transcript.messages)) throw new Error(`not an ${TRANSCRIPT_FORMAT} transcript`)
  const messages = transcript.messages.map((m, i) => {
    if (typeof m !== 'object' || m === null || Array.isArray(m) || typeof (m as { role?: unknown }).role !== 'string') {
      throw new Error(`transcript message ${i} has no role`)
    }
    return m as unknown as AgentMessage
  })
  return { messages, records: messages.flatMap((m) => (m.role === 'aigent' ? [m.record as unknown] : [])) }
}

/** Text fields only. Opaque provider fields such as thinking and text signatures pass through untouched. */
function exportMessage(message: AgentMessage, redact: (text: string) => string): AgentMessage {
  const text = <T extends { type: string }>(c: T): T => (c.type === 'text' ? { ...c, text: redact((c as unknown as { text: string }).text) } : c)
  switch (message.role) {
    case 'system':
      return {
        ...message,
        content: typeof message.content === 'string' ? redact(message.content) : message.content.map(text),
        ...(message.sections ? { sections: Object.fromEntries(Object.entries(message.sections).map(([k, v]) => [k, v === null ? v : redact(v)])) } : {}),
      }
    case 'user':
      return { ...message, content: typeof message.content === 'string' ? redact(message.content) : message.content.map(text) }
    case 'assistant':
      return {
        ...message,
        content: message.content.map((c) =>
          c.type === 'text' ? text(c) : c.type === 'thinking' ? { ...c, thinking: redact(c.thinking) } : { ...c, arguments: redactJson(c.arguments, redact) },
        ),
        ...(message.errorMessage ? { errorMessage: redact(message.errorMessage) } : {}),
      }
    case 'toolResult':
      return { ...message, content: message.content.map(text) }
    case 'aigent': {
      const { record } = message
      if (record.kind === 'denied') return { ...message, record: { ...record, reason: redact(record.reason) } }
      if (record.kind === 'pending') return { ...message, record: { ...record, text: redact(record.text) } }
      return message
    }
    default:
      return message satisfies never
  }
}

/**
 * Redacting each delta alone lets a listener rejoin a secret split across deltas. Any secret that could still be
 * completing starts within the last `longest - 1` characters, so those wait for more text or the message's end.
 */
function holdBack(longest: number, redact: (text: string) => string, emit: (delta: string) => void) {
  let held = ''
  return {
    push(delta: string): void {
      held = redact(held + delta)
      let cut = held.length - Math.max(0, longest - 1)
      // Never strand half of a surrogate pair at the end of a delta.
      if (cut > 0 && /[\uD800-\uDBFF]/.test(held[cut - 1]!)) cut -= 1
      if (cut <= 0) return
      emit(held.slice(0, cut))
      held = held.slice(cut)
    },
    flush(): void {
      if (held) emit(held)
      held = ''
    },
  }
}

/** Deep-redacts strings in our own JSON-shaped values. Image data is left alone. */
function redactJson<T>(value: T, redact: (text: string) => string): T {
  if (typeof value === 'string') return redact(value) as T
  if (Array.isArray(value)) return value.map((v) => redactJson(v, redact)) as T
  if (typeof value !== 'object' || value === null) return value
  const image = (value as { type?: unknown }).type === 'image'
  return Object.fromEntries(Object.entries(value).map(([k, v]) => [k, image && k === 'data' ? v : redactJson(v, redact)])) as T
}

function messageOf(error: unknown): string {
  return error instanceof Error ? error.message : String(error)
}

#!/usr/bin/env python3
"""Check a quiz file against the shape in references/quiz-file.md.

usage: quizlint [--plan] [--json] FILE
  --plan   the quiz has not run yet: no attempts and no outcome
  --json   print one JSON object: ok, problems, notes, and metrics

After the shape, it checks the words of each prompt, option, and key point.
A prompt over 40 words, an option over 20, a key point over 25, more than 4 key points,
or a correct option that its length gives away is an error: exit 1.
A word from the lists of references/plain-english.md, a code name, or a sentence
over 20 words in a prompt is a note to reread, not an error.
"""
import json
import os
import sys

sys.dont_write_bytecode = True  # keep the plugin tree free of __pycache__
sys.path.insert(0, os.path.dirname(os.path.realpath(__file__)))
from plain import HARD, HARD_RE, code_names, giveaway, sentences, words  # noqa: E402

ALTITUDES = {"design", "mechanism", "trivial"}
KINDS = {"single", "multi", "free"}
CATEGORIES = {"rationale", "failure", "extension", "boundary", "flow", "invalidation", "measurement"}
VERDICTS = {"pass", "vague", "wrong"}
RELEVANCE = {"core": 0, "important": 1, "useful": 2}
TOP_KEYS = {"version", "branch", "base", "head", "target", "altitude", "incidental",
            "examinee", "questions", "outcome", "findings"}
QUESTION_KEYS = {"id", "kind", "category", "relevance", "prompt", "options", "key_points", "attempts"}
ATTEMPT_KEYS = {"prompt", "kind", "options", "answer", "verdict", "feedback", "round"}
MAX_QUESTIONS = 10
MAX_PROMPT_WORDS = 40
MAX_OPTION_WORDS = 20
MAX_POINT_WORDS = 25
MAX_POINTS = 4
MAX_SENTENCE_WORDS = 20


def text(value):
    return isinstance(value, str) and value.strip() != ""


def check_options(where, kind, options, problems):
    if kind == "free":
        if options:
            problems.append(f"{where}: a free question has no options")
        return
    low, high = (2, 4) if kind == "single" else (3, 4)
    if not isinstance(options, list) or not low <= len(options) <= high:
        problems.append(f"{where}: a {kind} question has {low} to {high} options")
        return
    labels = [o.get("label") for o in options if isinstance(o, dict)]
    if len(labels) != len(options) or not all(text(label) for label in labels):
        problems.append(f"{where}: every option is {{\"label\": text, \"correct\": bool}}")
        return
    if len(set(labels)) != len(labels):
        problems.append(f"{where}: option labels repeat")
    correct = [o for o in options if o.get("correct") is True]
    if any(not isinstance(o.get("correct"), bool) for o in options):
        problems.append(f"{where}: every option says whether it is correct")
    if kind == "single" and len(correct) != 1:
        problems.append(f"{where}: a single question has exactly one correct option, not {len(correct)}")
    if kind == "multi" and not correct:
        problems.append(f"{where}: a multi question has at least one correct option")


def lint(quiz, plan):
    problems = []
    if not isinstance(quiz, dict):
        return ["the quiz file holds one JSON object"]
    for key in sorted(set(quiz) - TOP_KEYS):
        problems.append(f"unknown key {key!r}")
    if quiz.get("version") != 1:
        problems.append("version is 1")
    for key in ("branch", "base", "head", "target"):
        if not text(quiz.get(key)):
            problems.append(f"{key} is a non-empty string")
    if quiz.get("altitude") not in ALTITUDES:
        problems.append(f"altitude is one of {sorted(ALTITUDES)}")
    incidental = quiz.get("incidental", [])
    if not isinstance(incidental, list) or not all(text(i) for i in incidental):
        problems.append("incidental is a list of strings")
    examinee = quiz.get("examinee")
    if examinee not in {"human", "agent"}:
        problems.append("examinee is human or agent")

    questions = quiz.get("questions")
    if not isinstance(questions, list):
        return problems + ["questions is a list"]
    if len(questions) > MAX_QUESTIONS:
        problems.append(f"{len(questions)} questions, more than {MAX_QUESTIONS}")
    ids = set()
    for n, q in enumerate(questions, 1):
        where = f"question {n}"
        if not isinstance(q, dict):
            problems.append(f"{where}: is an object")
            continue
        for key in sorted(set(q) - QUESTION_KEYS):
            problems.append(f"{where}: unknown key {key!r}")
        qid = q.get("id")
        if not text(qid) or qid in ids:
            problems.append(f"{where}: id is a unique non-empty string")
        ids.add(qid)
        kind = q.get("kind")
        if kind not in KINDS:
            problems.append(f"{where}: kind is one of {sorted(KINDS)}")
            continue
        if examinee == "agent" and kind != "free":
            problems.append(f"{where}: an agent examinee gets free questions only")
        if q.get("category") not in CATEGORIES:
            problems.append(f"{where}: category is one of {sorted(CATEGORIES)}")
        if q.get("relevance") not in RELEVANCE:
            problems.append(f"{where}: relevance is one of {sorted(RELEVANCE, key=RELEVANCE.get)}")
        if not text(q.get("prompt")):
            problems.append(f"{where}: prompt is a non-empty string")
        check_options(where, kind, q.get("options"), problems)
        points = q.get("key_points")
        if not isinstance(points, list) or not points or not all(text(p) for p in points):
            problems.append(f"{where}: key_points is a non-empty list of strings")
        attempts = q.get("attempts")

        attempts = q.get("attempts")
        if plan:
            if attempts:
                problems.append(f"{where}: a plan has no attempts yet")
            continue
        if not isinstance(attempts, list) or not attempts:
            problems.append(f"{where}: has at least one attempt")
            continue
        for m, a in enumerate(attempts, 1):
            at = f"{where} attempt {m}"
            if not isinstance(a, dict):
                problems.append(f"{at}: is an object")
                continue
            for key in sorted(set(a) - ATTEMPT_KEYS):
                problems.append(f"{at}: unknown key {key!r}")
            answer = a.get("answer")
            if not (text(answer) or (isinstance(answer, list) and all(text(x) for x in answer))):
                problems.append(f"{at}: answer is the text or the picked labels")
            if a.get("verdict") not in VERDICTS:
                problems.append(f"{at}: verdict is one of {sorted(VERDICTS)}")

    relevance = [q.get("relevance") for q in questions if isinstance(q, dict)]
    if "core" in relevance or "important" in relevance:
        for n, q in enumerate(questions, 1):
            if isinstance(q, dict) and q.get("relevance") == "useful":
                problems.append(f"question {n}: a useful point gets a question only when the quiz would have none")

    ranks = [RELEVANCE.get(q.get("relevance")) for q in questions[:-1] if isinstance(q, dict)]
    if None not in ranks and ranks != sorted(ranks):
        problems.append("the questions run from most to least relevant, except the last")

    if examinee == "human" and len(questions) >= 2:
        kinds = [q.get("kind") for q in questions if isinstance(q, dict)]
        if kinds[0] != "single":
            problems.append("the quiz opens with a single question")
        if kinds[-1] not in {"multi", "free"}:
            problems.append("the quiz ends with a multi or a free question")

    outcome = quiz.get("outcome")
    if plan:
        if outcome is not None:
            problems.append("a plan has no outcome yet")
    elif outcome not in {"passed", "failed"}:
        problems.append("outcome is passed or failed")
    elif outcome == "passed":
        for n, q in enumerate(questions, 1):
            attempts = q.get("attempts") if isinstance(q, dict) else None
            if isinstance(attempts, list) and attempts and isinstance(attempts[-1], dict) \
                    and attempts[-1].get("verdict") != "pass":
                problems.append(f"question {n}: a passed quiz ends every question on a pass")
    return problems


def language(questions):
    """Check the words of each question. Returns problems, notes, and metrics."""
    problems, notes = [], []
    prompt_words, option_words, names, giveaways, fluff = [], [], [], 0, 0
    for n, q in enumerate(questions, 1):
        where = f"question {n}"
        prompt = q["prompt"]
        labels = [o["label"] for o in q.get("options") or []]
        points = q["key_points"]

        prompt_words.append(len(words(prompt)))
        if prompt_words[-1] > MAX_PROMPT_WORDS:
            problems.append(f"{where}: the prompt has {prompt_words[-1]} words, more than {MAX_PROMPT_WORDS}: "
                            "ask one thing in one or two short sentences")
        for label in labels:
            option_words.append(len(words(label)))
            if option_words[-1] > MAX_OPTION_WORDS:
                problems.append(f"{where}: an option has {option_words[-1]} words, more than {MAX_OPTION_WORDS}")
        for point in points:
            if len(words(point)) > MAX_POINT_WORDS:
                problems.append(f"{where}: a key point has {len(words(point))} words, more than {MAX_POINT_WORDS}")
        if len(points) > MAX_POINTS:
            problems.append(f"{where}: {len(points)} key points, more than {MAX_POINTS}")
        if q["kind"] == "single" and giveaway(q["options"]):
            giveaways += 1
            problems.append(f"{where}: the correct option is much longer than the wrong ones, so its length gives it away")

        hits = [m.group(0).lower() for t in [prompt, *labels, *points] for m in HARD_RE.finditer(t)]
        fluff += len(hits)
        for word in dict.fromkeys(hits):
            notes.append(f'{where}: "{word}": {HARD[word]}')
        found = code_names(" ".join([prompt, *labels]))
        names.append(len(found))
        for name in found:
            notes.append(f"{where}: code name {name}: say what it is in plain words, unless the question is about that name")
        for sentence in sentences(prompt):
            if len(words(sentence)) > MAX_SENTENCE_WORDS:
                notes.append(f"{where}: a sentence of {len(words(sentence))} words in the prompt: {sentence}")

    mean = lambda xs: round(sum(xs) / len(xs), 2) if xs else 0
    metrics = {"questions": len(questions),
               "prompt_words": mean(prompt_words), "prompt_words_max": max(prompt_words, default=0),
               "option_words": mean(option_words), "option_words_max": max(option_words, default=0),
               "code_names": mean(names), "giveaways": giveaways, "fluff": fluff}
    return problems, notes, metrics


